svg.metadata:
{"project": "EvidenceGraph", "diagram": "03_advanced_rag_architecture", "title": "EvidenceGraph — Advanced RAG and Knowledge Retrieval", "description": "Offline ingestion: document parsing, semantic chunking, dense embeddings, BM25 sparse encoding, and entity/claim extraction into Qdrant and Neo4j. Online retrieval: query expansion, dense retrieval, BM25, graph traversal, reciprocal rank fusion, reranking, context assembly, and grounded evidence to LangGraph.", "source_format": "graphviz_dot", "graphviz_dot": "digraph EvidenceGraphRAG {
 graph [label="EVIDENCEGRAPH / ADVANCED RAG & GRAPH RETRIEVAL", labelloc=t, labeljust=l,
 fontsize=25, fontname="DejaVu Sans", fontcolor="#142338", bgcolor="#FFFFFF",
 rankdir=LR, pad=0.4, nodesep=0.55, ranksep=0.68,
 splines=polyline, compound=true, newrank=true, outputorder=edgesfirst];
 node [shape=box, style="rounded,filled", fontname="DejaVu Sans", fontsize=13,
 color="#CBD5E1", fillcolor="#FFFFFF", fontcolor="#172E44", penwidth=1.4,
 margin="0.22,0.16"];
 edge [color="#7D91A9", penwidth=1.6, arrowsize=0.77, fontsize=10,
 fontname="DejaVu Sans", fontcolor="#64748B"];

 subgraph cluster_ingestion {
 label="01 / OFFLINE INGESTION & INDEXING"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D1E8DC"; fillcolor="#F4FBF7"; margin=18;
 documents [label="SOURCE MATERIAL\nPDFs · Papers · Web pages\nUploaded documents", fillcolor="#E0F1E7", color="#80B89D"];
 parse [label="Parse + normalize\nExtract text and metadata", fillcolor="#E0F1E7", color="#80B89D"];
 chunks [label="Semantic chunking\nStable IDs + provenance", fillcolor="#E0F1E7", color="#80B89D"];
 dense_embed [label="Dense embedding\nSemantic vectors", fillcolor="#E0F1E7", color="#80B89D"];
 bm25_index [label="BM25 sparse encoding\nLexical signals", fillcolor="#E0F1E7", color="#80B89D"];
 extract [label="Entity / claim extraction\nRelations + supporting spans", fillcolor="#E0F1E7", color="#80B89D"];
 documents -> parse -> chunks;
 chunks -> dense_embed;
 chunks -> bm25_index;
 chunks -> extract;
 {rank=same; dense_embed; bm25_index; extract}
 }

 subgraph cluster_storage {
 label="02 / KNOWLEDGE STORES"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#F0E0BB"; fillcolor="#FFFBF3"; margin=18;
 qdrant [label="Qdrant\nDense + sparse vectors\nChunk metadata", shape=cylinder, fillcolor="#FFF0D1", color="#D9B469"];
 neo [label="Neo4j\nEntities + relationships\nClaims + provenance", shape=cylinder, fillcolor="#FFF0D1", color="#D9B469"];
 {rank=same; qdrant; neo}
 }

 subgraph cluster_online {
 label="03 / ONLINE HYBRID RETRIEVAL"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D6E4F5"; fillcolor="#F5F9FF"; margin=18;
 query [label="USER QUESTION", fillcolor="#E2EEFE", color="#76A5D9"];
 expand [label="Query normalization\nRewrite / expand", fillcolor="#E2EEFE", color="#76A5D9"];
 dense [label="Dense similarity\nRetrieval", fillcolor="#E2EEFE", color="#76A5D9"];
 sparse [label="BM25 keyword\nRetrieval", fillcolor="#E2EEFE", color="#76A5D9"];
 traversal [label="Graph traversal\nEntity neighborhoods", fillcolor="#E2EEFE", color="#76A5D9"];
 rrf [label="Reciprocal Rank Fusion\nMerge dense + BM25", fillcolor="#E2EEFE", color="#76A5D9"];
 rerank [label="Reranking\nCross-encoder / LLM", fillcolor="#E2EEFE", color="#76A5D9"];
 context [label="Context assembly\nDedup · Graph enrichment\nSource metadata + citations", fillcolor="#E2EEFE", color="#76A5D9"];
 output [label="GROUNDED EVIDENCE\nTo LangGraph agents", fillcolor="#E2F5E8", color="#78BC94", penwidth=2];
 query -> expand;
 expand -> dense;
 expand -> sparse;
 expand -> traversal;
 dense -> rrf;
 sparse -> rrf;
 rrf -> rerank -> context -> output;
 traversal -> context;
 {rank=same; dense; sparse; traversal}
 }

 dense_embed -> qdrant [label="write"];
 bm25_index -> qdrant [label="write"];
 extract -> neo [label="write"];
 qdrant -> dense [label="search", color="#B8975A", fontcolor="#9D793C"];
 qdrant -> sparse [label="search", color="#B8975A", fontcolor="#9D793C"];
 neo -> traversal [label="traverse", color="#B8975A", fontcolor="#9D793C"];
}
"}
